/**
 * Zero-Backend Payload Decoder for SchedSolicit Viewer Portal.
 * Handles URL-safe base64 and GZIP compressed packages generated by the Flutter Owner App.
 */

export interface SharedDataset {
  v: number;
  label: string;
  exported_at: string;
  privacy?: {
    hide_amounts?: boolean;
    hide_contacts?: boolean;
  };
  schedules: any[];
  solicitations: any[];
}

export async function decodeSharePayload(rawCode: string): Promise<SharedDataset | null> {
  try {
    let clean = rawCode.trim();

    // Handle full URL pasted (e.g. https://domain.com/#d=SS1_...)
    if (clean.includes('#d=')) {
      clean = clean.split('#d=')[1];
    } else if (clean.includes('?d=')) {
      clean = clean.split('?d=')[1];
    }

    if (clean.includes('&')) {
      clean = clean.split('&')[0];
    }

    if (clean.startsWith('SS1_')) {
      clean = clean.substring(4);
    }

    // Replace URL-safe characters
    const standardBase64 = clean.replace(/-/g, '+').replace(/_/g, '/');
    const binaryStr = atob(standardBase64);
    const bytes = new Uint8Array(binaryStr.length);
    for (let i = 0; i < binaryStr.length; i++) {
      bytes[i] = binaryStr.charCodeAt(i);
    }

    // Try decompressing via native Web DecompressionStream (GZIP)
    if (typeof DecompressionStream !== 'undefined') {
      try {
        const ds = new DecompressionStream('gzip');
        const writer = ds.writable.getWriter();
        writer.write(bytes);
        writer.close();

        const reader = ds.readable.getReader();
        const chunks: Uint8Array[] = [];
        let done = false;
        let value: Uint8Array | undefined;

        while (!done) {
          const res = await reader.read();
          done = res.done;
          value = res.value;
          if (value) chunks.push(value);
        }

        const totalLength = chunks.reduce((acc, c) => acc + c.length, 0);
        const merged = new Uint8Array(totalLength);
        let offset = 0;
        for (const chunk of chunks) {
          merged.set(chunk, offset);
          offset += chunk.length;
        }

        const jsonStr = new TextDecoder().decode(merged);
        return JSON.parse(jsonStr) as SharedDataset;
      } catch (gzipErr) {
        // Fall through to plain text if not gzip compressed
      }
    }

    // Fallback: direct UTF-8 decoding
    const plainJson = new TextDecoder().decode(bytes);
    return JSON.parse(plainJson) as SharedDataset;
  } catch (err) {
    console.error('Failed to decode share payload:', err);
    return null;
  }
}
